begin;
select no_plan();
insert into auth.users(id,email,aud,role) values
('f3000000-0000-4000-8000-000000000001','arcade-a@example.invalid','authenticated','authenticated');
insert into public.pokemon_individuals(id,user_id,pokemon_id,personality,appearance,potential) values
('f4000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001',25,1,'{"v":2,"palette":"origin","shift":[[0,0,0],[0,0,0],[0,0,0]],"marks":null}','{"v":1,"offsets":[],"stars":1}');
create temp table rc(k text primary key,v jsonb);
grant all on rc to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f3000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into rc values ('block',public.minigame_start('block-lab','f4000000-0000-4000-8000-000000000001',1::smallint));
select is((select v->'view'->>'kind' from rc where k='block'),'block-lab','block lab typed view');
select is((public.minigame_status())->'games'->'block-lab'->>'left','4','block lab has separate turn budget');
select is(jsonb_array_length((select v->'view'->'queue' from rc where k='block')),1400,'block lab queue is 200 server bags');
select is((select v->'view'->>'goal' from rc where k='block'),'10','block lab goal comes from the difficulty');
select ok((select (v->'view'->>'elapsedMs')::int from rc where k='block')>=0,'block lab view carries the server clock');
select throws_ok($$select public.minigame_finish(((select v->>'round' from rc where k='block'))::uuid,'[]'::jsonb)$$,'P0001','not_finished','an empty log cannot finish a block round early');
select throws_ok($$select public.minigame_finish(((select v->>'round' from rc where k='block'))::uuid,'[[200,0],[100,0]]'::jsonb)$$,'P0001','bad_move','time cannot go backwards');
select throws_ok($$select public.minigame_finish(((select v->>'round' from rc where k='block'))::uuid,'[[100,9]]'::jsonb)$$,'P0001','bad_move','unknown action rejected');
select throws_ok($$select public.minigame_finish(((select v->>'round' from rc where k='block'))::uuid,'[[400000,0]]'::jsonb)$$,'P0001','bad_move','an input from the future is rejected');
select throws_ok($$select public.minigame_finish(((select v->>'round' from rc where k='block'))::uuid,'{}'::jsonb)$$,'P0001','bad_move','a log must be an array');
reset role;
