insert into rc values ('silhouette',public.minigame_start('silhouette-atelier','f4000000-0000-4000-8000-000000000001',1::smallint));
select is((select v->'view'->>'kind' from rc where k='silhouette'),'silhouette-atelier','jigsaw typed view');
select is((select v->'view'->>'cols' from rc where k='silhouette'),'2','easy grid has two columns');
select is((select v->'view'->>'rows' from rc where k='silhouette'),'3','easy grid has three rows');
select is(jsonb_array_length((select v->'view'->'rot' from rc where k='silhouette')),6,'easy grid has six pieces');
select is((select v->'view'->'rot' from rc where k='silhouette'),'[0,0,0,0,0,0]'::jsonb,'easy pieces start upright');
select ok((select (v->'view') ? 'artSpeciesId' from rc where k='silhouette'),'art id available to render');
select ok(not ((select v->'view' from rc where k='silhouette') ? 'speciesId'),'answer species remains private');
select throws_ok($$select public.minigame_finish(((select v->>'round' from rc where k='silhouette'))::uuid,'[]'::jsonb)$$,'P0001','not_finished','empty log cannot win');
select throws_ok($$select public.minigame_finish(((select v->>'round' from rc where k='silhouette'))::uuid,'{}'::jsonb)$$,'P0001','bad_move','log must be an array');
select throws_ok($$select public.minigame_finish(((select v->>'round' from rc where k='silhouette'))::uuid,'[[10,0,-1]]'::jsonb)$$,'P0001','bad_move','cannot return a piece that is in the tray');
select throws_ok($$select public.minigame_finish(((select v->>'round' from rc where k='silhouette'))::uuid,'[[10,0,0],[9,1,1]]'::jsonb)$$,'P0001','bad_move','timestamps cannot decrease');
select throws_ok($$select public.minigame_finish(((select v->>'round' from rc where k='silhouette'))::uuid,'[[10,0,0],[20,0,-2]]'::jsonb)$$,'P0001','bad_move','a locked piece cannot be turned');
select is((select (v->'view'->'rot') from rc where k='silhouette'),'[0,0,0,0,0,0]'::jsonb,'view keeps the starting turns');
